import detectEthereumProvider from '@metamask/detect-provider';
import { ethers } from 'ethers';
import * as nearAPI from 'near-api-js';
import { generateSeedPhrase } from 'near-seed-phrase';
import BN from 'bn.js';
import isMobile from 'is-mobile';

const nethIcon = `data:image/png;base64,`;

const NETH_SITE_URL = "https://neth.app";
const PREV_NETH_SITE_URL = "neardefi.github.io/neth";
const NETWORK = {
  testnet: {
    FUNDING_ACCOUNT_ID: "neth.testnet",
    MAP_ACCOUNT_ID: "map.neth.testnet",
    ROOT_ACCOUNT_ID: "testnet"
  },
  mainnet: {
    MAP_ACCOUNT_ID: "nethmap.near",
    ROOT_ACCOUNT_ID: "near"
  }
};

// Initialization and connection setup
let near, gas, keyStore, logger, storage, connection, networkId, contractAccount, accountSuffix;
const initConnection = ({ network, gas: _gas = "200000000000000", logger: _logger = () => ({ log: args => console.log(...args) }), storage: _storage = defaultStorage() }) => {
  gas = _gas;
  logger = _logger;
  storage = _storage;
  keyStore = new nearAPI.keyStores.BrowserLocalStorageKeyStore();
  near = new nearAPI.Near({ ...network, keyStore });
  connection = near.connection;
  networkId = network.networkId;
  contractAccount = new nearAPI.Account(connection, networkId === "mainnet" ? "near" : networkId);
  accountSuffix = networkId === "mainnet" ? ".near" : "." + networkId;
  broadcastTXs();
  return document.createElement("div");
};

// Ethereum provider detection and signer acquisition
const getEthereum = async () => {
  const provider = await detectEthereumProvider();
  if (!provider) {
    alert("Please install/activate MetaMask and try again.");
    return;
  }
  try {
    await window.ethereum.request({ method: "wallet_switchEthereumChain", params: [{ chainId: "0x" + domain.chainId.toString(16) }] });
  } catch (e) {
    if ((e.code || e.data?.originalError?.code) !== 4902) throw e;
    try {
      await window.ethereum.request({ method: "wallet_addEthereumChain", params: [{
        chainId: "0x" + domain.chainId.toString(16),
        chainName: "Aurora Mainnet",
        nativeCurrency: { name: "Ethereum", symbol: "ETH", decimals: 18 },
        blockExplorerUrls: ["https://explorer.mainnet.aurora.dev/"],
        rpcUrls: ["https://mainnet.aurora.dev"]
      }] });
    } catch (e2) {
      alert('Error adding chain. Please click "Choose Ethereum Account" and add the Aurora Network to continue.');
      throw e2;
    }
  }
  const ethersProvider = new ethers.providers.Web3Provider(window.ethereum);
  const accounts = await ethersProvider.listAccounts();
  if (accounts.length === 0) await ethersProvider.send("eth_requestAccounts", []);
  const signer = ethersProvider.getSigner();
  return { signer, ethAddress: await signer.getAddress() };
};

// NEAR account existence check
const accountExists = async (accountId, ethAddress = null) => {
  try {
    const account = new nearAPI.Account(connection, accountId);
    await account.state();
    if (ethAddress) {
      const mapAccountId = await getNearMap(ethAddress);
      if (mapAccountId) return true;
    }
    return true;
  } catch (e) {
    if (!/no such file|does not exist/.test(e.toString())) throw e;
    return false;
  }
};

// Account creation flow including keypair generation from Ethereum signature
const handleCreate = async (signer, ethAddress, newAccountId, fundingAccountCB, fundingErrorCB, postFundingCB) => {
  if ((networkId === "testnet" && newAccountId.includes(".near")) || (networkId === "mainnet" && newAccountId.includes(".testnet"))) {
    alert("Invalid account name. You do not need to add any .near or .testnet. Please try again.");
    return;
  }
  const { publicKey: fundingAccountPubKey, secretKey: new_secret_key } = await keyPairFromEthSig(signer, fundingKeyPayload());
  await storage.setItem(ATTEMPT_ACCOUNT_ID, newAccountId);
  await storage.setItem(ATTEMPT_SECRET_KEY, new_secret_key);
  await storage.setItem(ATTEMPT_ETH_ADDRESS, ethAddress);
  return await createAccount({ signer, newAccountId, fundingAccountPubKey, fundingAccountCB, fundingErrorCB, postFundingCB });
};

// Account creation with funding check, contract deployment, key rotation, and mapping
const createAccount = async ({ signer, newAccountId, fundingAccountPubKey, fundingAccountCB, fundingErrorCB, postFundingCB }) => {
  const implicitAccountId = Buffer.from(nearAPI.utils.PublicKey.from(fundingAccountPubKey).data).toString("hex");
  if (fundingAccountCB) fundingAccountCB(implicitAccountId);
  const checkImplicitFunded = async () => {
    const account = new nearAPI.Account(connection, implicitAccountId);
    try {
      const balance = await account.getAccountBalance();
      const diff = new BN(balance.available).sub(new BN(MIN_NEW_ACCOUNT_THRESH));
      if (diff.lt(new BN("0"))) {
        if (fundingErrorCB) fundingErrorCB(implicitAccountId, diff.abs().toString());
        await new Promise(r => setTimeout(r, FUNDING_CHECK_TIMEOUT));
        return await checkImplicitFunded();
      }
    } catch (e) {
      if (!/does not exist/gi.test(e.toString())) throw e;
      await new Promise(r => setTimeout(r, FUNDING_CHECK_TIMEOUT));
      return await checkImplicitFunded();
    }
    return true;
  };
  if (!(await checkImplicitFunded())) return window.location.reload();
  if (postFundingCB) postFundingCB();
  const { account, ethAddress } = await setupFromStorage(implicitAccountId);
  if (await accountExists(newAccountId, ethAddress)) {
    alert(`${newAccountId} already exists. Please try another.`);
    return await handleCancelFunding(implicitAccountId);
  }
  const { publicKey: new_public_key, secretKey: new_secret_key } = await keyPairFromEthSig(signer, unlimitedKeyPayload(newAccountId, ethAddress));
  await storage.setItem(ATTEMPT_SECRET_KEY, new_secret_key);
  await storage.removeItem(APP_KEY_ACCOUNT_ID);
  await storage.removeItem(APP_KEY_SECRET);
  try {
    await account.functionCall({
      contractId: NETWORK[networkId].ROOT_ACCOUNT_ID,
      methodName: "create_account",
      args: { new_account_id: newAccountId, new_public_key },
      gas,
      attachedDeposit: new BN(MIN_NEW_ACCOUNT)
    });
  } catch (e) {
    if (!/be created by/.test(JSON.stringify(e))) throw e;
    return handleCancelFunding(implicitAccountId);
  }
  if (!(await accountExists(newAccountId))) {
    logger.log(`Account ${newAccountId} could NOT be created. Please refresh the page and try again.`);
    return;
  }
  logger.log(`Account ${newAccountId} created successfully.`);
  await account.deleteAccount(newAccountId);
  return await handleMapping();
};

// Account mapping to Ethereum address
const handleMapping = async () => {
  const { account, ethAddress } = await setupFromStorage();
  try {
    await account.functionCall({
      contractId: NETWORK[networkId].MAP_ACCOUNT_ID,
      methodName: "set",
      args: { eth_address: ethAddress },
      gas,
      attachedDeposit: new BN(attachedDepositMapping)
    });
    logger.log(`Account mapping successful`);
  } catch (e) {
    logger.log(e);
    logger.log(`Account mapping failed`);
  }
  return await handleDeployContract();
};

// Contract deployment and setup
const handleDeployContract = async () => {
  const { account } = await setupFromStorage();
  const contractPath = window?.contractPath;
  const ab = await fetch(contractPath).then(res => res.arrayBuffer());
  const contractBytes = new Uint8Array(ab);
  try {
    await account.deployContract(contractBytes);
    logger.log(`Contract deployed successfully.`);
  } catch (e) {
    logger.log(e);
    logger.log(`Contract deployment failed. Please refresh the page and try again.`);
  }
  return await handleSetupContract();
};

const handleSetupContract = async () => {
  const { account, ethAddress } = await setupFromStorage();
  try {
    await account.functionCall({
      contractId: account.accountId,
      methodName: "setup",
      args: { eth_address: ethAddress },
      gas
    });
    logger.log(`Contract setup successfully.`);
  } catch (e) {
    logger.log(e);
    logger.log(`Contract setup failed. Please refresh the page and try again.`);
  }
  return await handleKeys();
};

// Key rotation for access keys
const handleKeys = async () => {
  const { account, newAccountId, ethAddress } = await setupFromStorage();
  const accessKeys = await account.getAccessKeys();
  if (accessKeys.length !== 1 || accessKeys[0]?.access_key?.permission !== "FullAccess") return;
  const publicKey = nearAPI.utils.PublicKey.from(accessKeys[0].public_key);
  const actions = [
    nearAPI.transactions.deleteKey(publicKey),
    nearAPI.transactions.addKey(publicKey, nearAPI.transactions.functionCallAccessKey(newAccountId, ["execute"]))
  ];
  try {
    const res = await account.signAndSendTransaction({ receiverId: newAccountId, actions });
    if (res?.status?.SuccessValue !== "") {
      logger.log(`Key rotation failed. Please refresh the page and try again.`);
      return;
    }
    logger.log(`Key rotation successful.`);
  } catch (e) {
    logger.log(e);
    logger.log(`Key rotation failed. Please refresh the page and try again.`);
  }
  return await handleCheckAccount({ ethAddress });
};

// Account check and recovery flow
const handleCheckAccount = async ({ signer = null, ethAddress = null, fundingAccountCB = null, fundingErrorCB = null, postFundingCB = null }) => {
  const setup = await setupFromStorage();
  let { newAccountId } = setup;
  const { newSecretKey } = setup;
  const mapAccountId = await getNearMap(ethAddress);
  if (!mapAccountId) {
    logger.log("No account mapping exists.");
  } else {
    newAccountId = mapAccountId;
  }
  logger.log("Checking account created.");
  if (!(await accountExists(newAccountId))) {
    const keyPair = nearAPI.KeyPair.fromString(newSecretKey);
    return createAccount({ signer, newAccountId, fundingAccountPubKey: keyPair.getPublicKey().toString(), fundingAccountCB, fundingErrorCB, postFundingCB });
  }
  const account = new nearAPI.Account(connection, newAccountId);
  logger.log("Checking account address mapping.");
  const mapRes = await account.viewFunction({ contractId: NETWORK[networkId].MAP_ACCOUNT_ID, methodName: "get_eth", args: { account_id: newAccountId } });
  if (mapRes === null) return handleMapping();
  logger.log("Checking contract deployed.");
  const state = await account.state();
  if (state.code_hash === "11111111111111111111111111111111") return handleDeployContract();
  logger.log("Checking contract setup.");
  try {
    const ethRes = await account.viewFunction({ contractId: newAccountId, methodName: "get_address" });
    if (!ethRes || !ethRes.length) return handleSetupContract();
  } catch (e) {
    logger.log(e);
    return handleSetupContract();
  }
  logger.log("Checking access keys.");
  const accessKeys = await account.getAccessKeys();
  if (accessKeys.length === 1 && accessKeys[0]?.access_key?.permission === "FullAccess") return handleKeys();
  logger.log("Account created.");
  logger.log("Contract deployed and setup.");
  logger.log("Mapping added.");
  logger.log("Keys rotated.");
  await storage.removeItem(ATTEMPT_ACCOUNT_ID);
  await storage.removeItem(ATTEMPT_SECRET_KEY);
  await storage.removeItem(ATTEMPT_ETH_ADDRESS);
  return { account };
};

