const signAndSendTransactions = async ({ transactions, bundle }) => {
  const ethRes = await getEthereum();
  const { signer } = ethRes;
  const nearAccount = await getNear();
  if (!nearAccount) {
    logger.log("NETH: ERROR signing and sending transactions. No account found.");
    return;
  }
  const { account, accountId } = nearAccount;
  const receivers = transactions.map(({ receiverId }) => receiverId);
  const transformedTxs = transactions.map(({ receiverId, actions }) => ({ actions: convertActions(actions, accountId, receiverId) }));
  const nonce = parseInt(await account.viewFunction({ contractId: accountId, methodName: "get_nonce" }), 16);
  const args = [];
  if (!bundle) {
    for (let i = 0; i < transformedTxs.length; i++) {
      args.push(await ethSignJson(signer, { nonce: (nonce + i).toString(), receivers: [receivers[i]], transactions: [transformedTxs[i]] }));
    }
  } else {
    args.push(await ethSignJson(signer, { nonce: nonce.toString(), receivers, transactions: transformedTxs }));
  }
  await storage.setItem(TX_ARGS_ATTEMPT, args);
  const res = await broadcastTXs();
  return res;
};

const broadcastTXs = async () => {
  const nearAccount = await getNear();
  if (!nearAccount) {
    logger.log("NETH: ERROR broadcasting tx. No account found.");
    return;
  }
  const { account, accountId } = nearAccount;
  const args = await storage.getItem(TX_ARGS_ATTEMPT);
  if (!args || args.length === 0) return;
  const res = [];
  while (args.length > 0) {
    const currentArgs = args.shift();
    logger.log("NETH: broadcasting tx", currentArgs);
    try {
      const tx = await account.functionCall({ contractId: accountId, methodName: "execute", args: currentArgs, gas });
      await storage.setItem(TX_ARGS_ATTEMPT, args);
      res.push(tx);
    } catch (e) {
      logger.log("NETH: ERROR broadcasting tx", e);
    }
  }
  await storage.removeItem(TX_ARGS_ATTEMPT);
  return res;
};
